CREATE TABLE employee
(
	pk_id serial NOT NULL,	-- Employee identifier
	fk_physical_location integer NULL,	-- Identify the physical point that the employee belongs to. This field can be NULL if its role is administrator
	name varchar(25) NOT NULL,	-- Employee name
	last_name varchar(25) NOT NULL,	-- Employee last name
	telephone varchar(15) NOT NULL,	-- Employee telephone It must be a number and can't begin with 0
	role varchar(13) NOT NULL,	-- Employee role in the company, depending on its value, the employee will have a specific set of permissions. Only the following values should be allowed:      - Administrator     - Manager     - Cashier
	password varchar(300) NOT NULL	-- Employee password for get access
)
;

CREATE TABLE inventory
(
	pk_fk_product integer NOT NULL,	-- Identifier of the product stored in the inventory associated with a physical location
	pk_fk_physical_location integer NOT NULL,	-- Identifier of the physical location that own of the inventory
	amount smallint NOT NULL	-- Amount of the product stored at the physical location
)
;

CREATE TABLE physical_location
(
	pk_id serial NOT NULL,	-- Physical location identifier
