	telephone varchar(15) NOT NULL	-- The telephone number of the physical location. It must be a number and can't begin with 0
)
;

CREATE TABLE product
(
	pk_id serial NOT NULL,	-- Identifier of product
	fk_id_base_product integer NULL,	-- Given that the products can have variants. This field has the identifier of base product.
	name varchar(25) NOT NULL,	-- Name of product
