	price integer NOT NULL,	-- Sell price of product
	image text NOT NULL,	-- File name that contains the image of the product
	fk_category integer NOT NULL	-- References the category that the product belongs to
)
;

CREATE TABLE purchase
(
	pk_id serial NOT NULL,	-- Identificador de la compra
	date date NOT NULL,	-- Date when the purchase was made
	total_price integer NOT NULL,	-- Total purchase value It's dynamically calculated
	email varchar(75) NOT NULL,	-- Email address of the person who made the purchase Must be a valid email address in the form: abc@dfg.hi
	name varchar(45) NOT NULL,	-- Full Name of the shopper
	doc_type varchar(2) NOT NULL,	-- Type of the identification of the shopper Allowed values:     - CC     - TI     - CE In capital letters
	identification varchar(15) NOT NULL,	-- Identification number of the person who made the purchase Must be a number and can't begin with 0
	telephone varchar(15) NOT NULL,	-- Telephone number of the person who made the purchase
	is_physic_purchase boolean NOT NULL,	-- Indicates whether the purchase was made at a physical location or, alternatively, was made online
	delivery_address varchar(55) NULL,	-- Delivery address for online purchases. It only has a value if the purchase was online
	fk_department integer NULL,	-- Department where the delivery address is located It only has a value if the purchase was online
	zip_code varchar(6) NULL	-- Zip code corresponding to the delivery address It must be a number and can't begin with 0 It only has a value if the purchase was online
)
;

